import {MapView,bindMap} from './rover-map.js';
import {DEFAULTS,parameters,coordinates,gridPosition,metres} from './rover-core.js';
import {validateClimate,sampleClimate,FIELDS} from './environment.js';
const $=id=>document.getElementById(id),form=$('rover-form'),canvas=$('terrain-map'),ctx=canvas.getContext('2d');
const fmt=(x,n=2)=>Number.isFinite(x)?x.toLocaleString('en-US',{maximumFractionDigits:n,minimumFractionDigits:n}):'—';
let dem=null,grid=null,worker=null,workerReady=false,report=null,climate=null,start=null,goal=null,exclusions=[],mode='pan',epoch=0,busy=false,elapsedMs=0,climateEpoch=0,baseImage=null;
let regions=[],region=null,photo=null,loadEpoch=0,loadingRegion=false;const view=new MapView();
function values(){const p={...DEFAULTS};for(const el of form.elements)if(el.name in p)p[el.name]=el.type==='checkbox'?el.checked:Number(el.value);p.ambientC=climate.temperatureC;return parameters(p);}
function pointInputs(){for(const [name,p]of [['start',start],['goal',goal]])for(const k of ['lat','lon'])$(name+'-'+k).value=p[k].toFixed(5);$('point-summary').textContent=`① ${start.lat.toFixed(5)}°, ${start.lon.toFixed(5)}° → ② ${goal.lat.toFixed(5)}°, ${goal.lon.toFixed(5)}°. Scenario zones: ${exclusions.length}.`;if($('terrain-lab-link')&&start)$('terrain-lab-link').href=`http://127.0.0.1:4174/?${new URLSearchParams({lat:start.lat.toFixed(4),lon:start.lon.toFixed(4),span:'1',name:region?.name||'Jezero Mission Zone'})}`;}
function clearResults(message){report=null;epoch++;$('export').disabled=$('print').disabled=true;$('result-title').textContent='Recalculation required';$('result-description').textContent=message;$('metrics').replaceChildren();$('comparison').innerHTML='<tr><td colspan="5">'+message+'</td></tr>';$('certificate').textContent='Optimality has not been verified for the updated conditions.';$('profile').innerHTML='<text x="20" y="100">Recalculate the route</text>';$('energy-breakdown').replaceChildren();baseImage=null;draw();}
function invalidate(){clearResults('Conditions changed. Select “Calculate route”.');$('status').textContent='Conditions changed — recalculate the route.';$('calculate').disabled=loadingRegion||!climate||!workerReady;}
async function launchWorker(){worker?.terminate();workerReady=false;const active=worker=new Worker('./rover-worker.js',{type:'module'});return new Promise((resolve,reject)=>{
 active.onerror=e=>{if(worker!==active)return;busy=false;workerReady=false;$('status').textContent='Calculation error: '+e.message;$('retry').hidden=false;reject(Error(e.message));};
 active.onmessage=({data})=>{if(worker!==active)return;if(data.type==='ready'){grid=data.grid;workerReady=true;resolve();}else if(data.type==='error'){if(data.id===undefined){reject(Error(data.message));return;}if(data.id!==epoch)return;busy=false;$('calculate').disabled=false;$('status').textContent=data.message;clearResults('Calculation failed: check the endpoints and parameters.');}else if(data.type==='result'&&data.id===epoch){busy=false;report=data.report;elapsedMs=data.elapsedMs;$('calculate').disabled=false;renderReport();baseImage=null;draw();}};
 active.postMessage({type:'init',dem});});}
async function loadClimate(){const token=++climateEpoch;climate=null;$('calculate').disabled=true;$('climate-context').textContent='Loading MCD 6.2…';const season=$('season').value,hour=$('hour').value;
 try{const r=await fetch(`./data/climate-${season}-${hour}.json`);if(!r.ok)throw Error('Climate scenario unavailable');const model=validateClimate(await r.json());if(token!==climateEpoch)return;
  const corners=[[0,0],[dem.width-1,0],[0,dem.height-1],[dem.width-1,dem.height-1]].map(([x,y])=>coordinates(dem,x,y));const samples=corners.map(p=>sampleClimate(model,p.lat,p.lon));
  climate={source:model.source,scenario:model.scenario,retrievedAt:model.retrievedAt,solarLongitude:model.solarLongitude,localSolarHour:model.localSolarHour,temperatureC:Math.min(...samples.map(s=>s.values.airTemperatureK)),gridCells:[...new Set(samples.map(s=>s.cell))],ranges:Object.fromEntries(Object.keys(FIELDS).map(k=>[k,{min:Math.min(...samples.map(s=>s.values[k])),max:Math.max(...samples.map(s=>s.values[k]))}]))};
  $('climate-context').textContent=`MCD 6.2 · Ls ${season}° · ${hour}:00. Heating-model temperature: ${fmt(climate.temperatureC,1)} °C (coldest of ${climate.gridCells.length} cells covering the area). Wind: ${fmt(climate.ranges.windSpeedMs.max,1)} m/s; dust τ: ${fmt(climate.ranges.dustOpticalDepth.max)}. Climatology, not current weather.`;$('calculate').disabled=loadingRegion||!workerReady;$('retry').hidden=true;
 }catch(e){if(token!==climateEpoch)return;$('climate-context').textContent=e.message;$('status').textContent='Heating cannot be calculated without a climate scenario.';$('retry').hidden=false;throw e;}}
async function load(){try{const r=await fetch('./data/mission-regions.json');if(!r.ok)throw Error('Zone catalogue unavailable');regions=await r.json();$('mission-region').replaceChildren(...regions.map(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.name;return o;}));$('mission-region').disabled=false;const id=new URLSearchParams(location.search).get('region');await loadRegion(regions.find(r=>r.id===id)||regions[0],true);}catch(e){$('status').textContent=e.message;$('retry').hidden=false;}}
async function loadRegion(selected,useQuery=false){
 const token=++loadEpoch;loadingRegion=true;epoch++;climateEpoch++;worker?.terminate();worker=null;workerReady=false;grid=null;dem=null;photo=null;climate=null;exclusions=[];region=selected;view.fit();
 $('mission-region').value=selected.id;$('calculate').disabled=true;clearResults('Loading selected mission zone…');ctx.clearRect(0,0,canvas.width,canvas.height);$('status').textContent='Loading measured terrain…';$('retry').hidden=true;$('region-description').textContent=selected.description;$('imagery-status').textContent='Loading registered orbital imagery…';
 try{const r=await fetch(selected.dem);if(!r.ok)throw Error('Terrain unavailable');const data=await r.json();if(token!==loadEpoch)return;dem=data;start={...dem.anchors.start};goal={...dem.anchors.goal};
 if(useQuery){const q=new URLSearchParams(location.search);for(const [prefix,point]of [['start',start],['goal',goal]])if(q.has(prefix+'Lat')&&q.has(prefix+'Lon')){point.lat=Number(q.get(prefix+'Lat'));point.lon=Number(q.get(prefix+'Lon'));}const inside=p=>{if(!Number.isFinite(p.lat)||!Number.isFinite(p.lon))return false;const q=gridPosition(dem,p);return q.x>=0&&q.y>=0&&q.x<dem.width&&q.y<dem.height;};if(!inside(start)||!inside(goal)){start={...dem.anchors.start};goal={...dem.anchors.goal};$('region-description').textContent+=' Atlas endpoints are outside this zone; demonstration endpoints are shown.';}}
 pointInputs();const images=new Promise(resolve=>{const img=new Image();img.onload=()=>{if(token===loadEpoch){photo=img;baseImage=null;draw();$('imagery-status').textContent='HiRISE orthoimage · display '+fmt(selected.imageResolutionM,2)+' m/px · source '+fmt(selected.nativeImageResolutionM,2)+' m/px. Registered to the terrain footprint.';const link=document.createElement('a');link.href=selected.imagePageUrl;link.target='_blank';link.rel='noopener';link.textContent=' Source ↗';$('imagery-status').append(link);}resolve();};img.onerror=()=>{if(token===loadEpoch)$('imagery-status').textContent='Image unavailable: showing elevation fallback.';resolve();};img.src=selected.image;});
 await Promise.all([launchWorker(),loadClimate(),images]);if(token!==loadEpoch)return;loadingRegion=false;$('calculate').disabled=false;$('image-resolution').textContent=fmt(selected.imageResolutionM,2)+' m';$('graph-resolution').textContent=fmt(grid.dx,2)+' m';const p=dem.provenance;$('source-details').textContent=p.title+'. Native terrain: '+fmt(dem.dx,2)+' m. Graph: '+grid.width+' × '+grid.height+' at '+fmt(grid.dx,2)+' m projected spacing. Missing elevations remain blocked. Source: '+p.sourceUrl;baseImage=null;draw();await calculate();
 }catch(e){if(token!==loadEpoch)return;loadingRegion=false;$('status').textContent='Zone unavailable: '+e.message;$('retry').hidden=false;}}
async function calculate(){if(loadingRegion||!dem||!climate)return;if(!form.reportValidity())return;
 try{const p=values();clearResults('Searching the current graph…');const id=epoch;busy=true;$('calculate').disabled=true;$('status').textContent='Calculating energy, constraints and independent verification…';if(!workerReady||busy&&worker._running)await launchWorker();if(id!==epoch)return;worker._running=true;worker.postMessage({type:'plan',id,start,goal,parameters:p,exclusions});}
 catch(e){busy=false;$('calculate').disabled=false;$('status').textContent=e.message;}}
function terrainImage(){if(!grid)return;const off=document.createElement('canvas');off.width=grid.width;off.height=grid.height;const c=off.getContext('2d'),im=c.createImageData(grid.width,grid.height),finite=Array.from(grid.values).filter(Number.isFinite),min=Math.min(...finite),max=Math.max(...finite),limit=Number(form.elements.maxSlopeDeg.value)||12;
 for(let y=0;y<grid.height;y++)for(let x=0;x<grid.width;x++){const i=y*grid.width+x,z=grid.values[i],k=i*4;let rgb;
  if(!Number.isFinite(z))rgb=[28,37,46];else if($('map-layer').value==='slope'){const f=Math.min(1,grid.slopes[i]/limit);rgb=[66+150*f,111-54*f,119-56*f];}
  else{const f=(z-min)/(max-min||1),l=grid.values[i-1]??z,r=grid.values[i+1]??z,u=grid.values[i-grid.width]??z,d=grid.values[i+grid.width]??z;const gx=Number.isFinite(r-l)?(r-l)/(2*grid.dx):0,gy=Number.isFinite(d-u)?(d-u)/(2*Math.abs(grid.dy)):0;const shade=Math.max(.3,Math.min(1.25,.82-gx*1.3-gy*.7));rgb=[(94+89*f)*shade,(82+70*f)*shade,(69+49*f)*shade];if(Math.abs(z/20-Math.round(z/20))<.035)rgb=rgb.map(v=>v*.65);}
  const blocked=report?report.blocked[i]:!Number.isFinite(z)||grid.slopes[i]>limit||exclusions.some(zone=>metres(grid.coords[i],zone,grid.projection.radius)<=zone.radiusM+Math.hypot(grid.dx,grid.dy)/2);
  if(blocked&&$('show-blocked').checked&&Number.isFinite(z))rgb=rgb.map((v,j)=>v*.35+[100,26,50][j]*.65);
  if(report?.visited?.[i]&&$('show-search').checked)rgb=rgb.map((v,j)=>v*.55+[73,144,176][j]*.45);
  let alpha=255;if($('map-layer').value==='imagery'&&photo){alpha=0;if(blocked&&$('show-blocked').checked){rgb=[190,45,85];alpha=130;}if(report?.visited?.[i]&&$('show-search').checked){rgb=[73,144,176];alpha=120;}}im.data.set([...rgb.map(v=>Math.round(Math.min(255,v))),alpha],k);
 }c.putImageData(im,0,0);return off;}
function draw(){if(!grid||!start||!goal)return;if(!baseImage)baseImage=terrainImage();ctx.clearRect(0,0,canvas.width,canvas.height);ctx.save();ctx.scale(view.zoom,view.zoom);ctx.translate(-view.x*canvas.width,-view.y*canvas.height);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';const layer=$('map-layer').value;if(photo&&(layer==='imagery'||layer==='hybrid'))ctx.drawImage(photo,0,0,canvas.width,canvas.height);ctx.globalAlpha=photo&&layer==='hybrid'?.35:1;ctx.drawImage(baseImage,0,0,canvas.width,canvas.height);ctx.globalAlpha=1;const sx=canvas.width/grid.width,sy=canvas.height/grid.height;
 function path(nodes,color,width,dash=[]){if(!nodes?.length)return;ctx.beginPath();nodes.forEach((n,i)=>{const x=(n%grid.width+.5)*sx,y=(Math.floor(n/grid.width)+.5)*sy;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.strokeStyle='#071119cc';ctx.lineWidth=(width+3)/view.zoom;ctx.setLineDash([]);ctx.stroke();ctx.strokeStyle=color;ctx.lineWidth=width/view.zoom;ctx.setLineDash(dash.map(v=>v/view.zoom));ctx.stroke();ctx.setLineDash([]);}
 if(report){if($('show-direct').checked)path(report.direct?.path,'#ef8c85',2,[8,9]);if($('show-shortest').checked)path(report.shortest?.path,'#73c6ec',3,[12,7]);if(report.status==='optimal')path(report.path,'#ffdd7a',5);}
 for(const zone of exclusions){const q=gridPosition(grid,zone);ctx.beginPath();ctx.arc((q.x+.5)*sx,(q.y+.5)*sy,zone.radiusM/grid.dx*sx,0,Math.PI*2);ctx.strokeStyle='#ff9abb';ctx.lineWidth=2;ctx.stroke();}
 for(const [p,label,color]of [[start,'①','#f0e6c8'],[goal,'②','#ffdc7a']]){const q=gridPosition(grid,p);if(q.x<0||q.y<0||q.x>=grid.width||q.y>=grid.height)continue;const x=(q.x+.5)*sx,y=(q.y+.5)*sy;ctx.beginPath();ctx.arc(x,y,13/view.zoom,0,2*Math.PI);ctx.fillStyle='#101c26';ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=3;ctx.stroke();ctx.font='bold '+(17/view.zoom)+'px Arial';ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,x,y);}
 ctx.restore();const span=metres(coordinates(grid,0,grid.height/2),coordinates(grid,grid.width,grid.height/2),grid.projection.radius)/view.zoom;const target=span*.2,power=10**Math.floor(Math.log10(target));const distance=[1,2,5,10].map(v=>v*power).filter(v=>v<=target).at(-1)||power;const scale=document.querySelector('.map-scale');scale.style.width=(distance/span*100)+'%';scale.textContent=distance>=1000?fmt(distance/1000,1)+' km':fmt(distance,0)+' m';scale.style.borderBottom='2px solid #f2e7d3';}
function renderReport(){const r=report;const statuses={optimal:'Minimum energy found',infeasible:'Insufficient resources', 'no-path':'No feasible path in this area','blocked-endpoint':'Start or target is in a blocked cell','search-limit':'Search incomplete'};$('result-title').textContent=statuses[r.status]||r.status;$('status').textContent=`${statuses[r.status]||r.status} · ${fmt(elapsedMs/1000,2)} s`;
 $('result-description').textContent=r.status==='optimal'?`The route satisfies the model constraints. ${r.assumptions.roundTrip?'Same-path return is included.':'A one-way trip was calculated.'} These data do not establish physical crew safety.`:r.status==='search-limit'?'The search-state limit was reached. This does NOT prove that no path exists. Increase autonomy or shorten the route.':r.status==='blocked-endpoint'?'Move the point to a traversable cell or adjust the slope limit with appropriate justification.':r.status==='no-path'?'No connected path exists in this area under the selected slope limit, data and exclusions. Routes outside this area were not explored.':'No route on this graph meets the resource budgets. Check energy, autonomy, reserve and science-stop duration.';
 const m=r.metrics;if(m){const cards=[['Mission energy',fmt(m.energy)+' kWh',`Available after reserve: ${fmt(r.energyBudget)}`],['Mission time',fmt(m.hours)+' h',`Available after reserve: ${fmt(r.timeBudget)} h`],['Margin above reserve',fmt(m.energyMargin)+' kWh',`Time margin: ${fmt(m.timeMargin)} h`],['Distance to target',fmt(m.oneWayKm)+' km',`Maximum cell slope: ${fmt(m.maxSlopeDeg,1)}°`]];$('metrics').innerHTML=cards.map(([a,b,c])=>`<div class="metric"><small>${a}</small><strong>${b}</strong><span>${c}</span></div>`).join('');drawProfile(r.profile);const total=m.energy;$('energy-breakdown').innerHTML=`<div class="energy-bar"><i style="width:${100*m.rolling/total}%"></i><i style="width:${100*m.climb/total}%"></i><i style="width:${100*m.hotel/total}%"></i></div>Rolling ${fmt(m.rolling)} · Ascent ${fmt(m.climb)} · Auxiliary + heating ${fmt(m.hotel)} kWh`;}else{$('metrics').replaceChildren();$('profile').innerHTML='<text x="20" y="100">No feasible route obtained</text>';$('energy-breakdown').replaceChildren();}
 const rows=[['Direct line',r.direct?.metrics,r.direct?.status==='blocked'?'Crosses a blocked area':''],['Shortest traversable',r.shortest?.metrics,r.shortest?.path?.length?'':'No path'],['Minimum energy',m,r.status==='optimal'?'':statuses[r.status]]];
 $('comparison').innerHTML=rows.map(([name,x,error],i)=>{const good=x&&x.energy<=r.energyBudget&&x.hours<=r.timeBudget;return `<tr class="${i===2?'selected':''}"><td>${name}</td><td>${x?fmt(x.oneWayKm)+' km':'—'}</td><td>${x?fmt(x.energy,3)+' kWh':'—'}</td><td>${x?fmt(x.hours)+' h':'—'}</td><td class="${good?'good':'bad'}">${error||(good?'Within model limits':'Exceeds a resource budget')}</td></tr>`;}).join('');
 const saving=m&&r.shortest?.metrics?(r.shortest.metrics.energy-m.energy)/r.shortest.metrics.energy*100:null;$('comparison-note').textContent=`Distance is one way; resources cover the entire mission. ${saving!==null?`Energy versus the shortest traversable route: ${saving>=0?fmt(saving,2)+'% less':fmt(-saving,2)+'% more; the shortest path does not satisfy all constraints'}.`:''} Points snapped to the grid: start offset ${fmt(r.snapMetres?.start,1)} m, target offset ${fmt(r.snapMetres?.goal,1)} m.`;
 if(r.status==='optimal'){$('certificate').innerHTML=`<b>Optimality on the current graph is verified.</b><br>${r.verification?`A*: ${fmt(r.verification.energyAStar,6)} kWh. Dijkstra: ${fmt(r.verification.energyDijkstra,6)} kWh. Difference: ${r.verification.delta.toExponential(2)} kWh.`:`Resource-constrained A* with exact nondominated energy/time pairs. Lower bound at completion: ${fmt(r.lowerBound,6)} kWh.`}<br>Gap to the lower bound: 0% (within JavaScript arithmetic). Expanded states: ${r.expanded.toLocaleString('en-US')}. Graph: ${grid.width} × ${grid.height}, spacing ${fmt(grid.dx,2)} m. No claim of optimality outside this model.`;}else $('certificate').textContent=r.status==='search-limit'?'No optimality certificate: the search stopped at its computation limit.':'No route selected. No claim of optimality for a successful mission.';
 $('export').disabled=false;$('print').disabled=false;}
function drawProfile(points){if(!points.length)return;const z=points.map(p=>p.elevationM),lo=Math.min(...z),hi=Math.max(...z),dist=[0];for(let i=1;i<points.length;i++)dist[i]=dist[i-1]+metres(points[i-1],points[i],grid.projection.radius);const total=dist.at(-1)||1;const path=points.map((p,i)=>`${i?'L':'M'}${45+dist[i]/total*535},${165-(p.elevationM-lo)/(hi-lo||1)*125}`).join(' ');$('profile').innerHTML=`<path d="${path} L580,170 L45,170 Z" fill="#d6bb9120"/><path d="${path}" fill="none" stroke="#e8c47e" stroke-width="2"/><text x="8" y="25">${fmt(hi,0)} m</text><text x="8" y="185">${fmt(lo,0)} m</text><text x="45" y="205">Start</text><text x="480" y="205">${fmt(total/1000)} km</text>`;}
bindMap(canvas,view,{getGrid:()=>loadingRegion?null:grid,getMode:()=>mode,draw,pick:q=>{const p=coordinates(grid,q.x*grid.width-.5,q.y*grid.height-.5);if(mode==='zone'){if(exclusions.length>=20)return;exclusions.push({...p,radiusM:Math.min(150,grid.width*grid.dx*.05)});}else if(mode==='start')start=p;else goal=p;pointInputs();invalidate();},hover:q=>{const x=Math.max(0,Math.min(grid.width-1,Math.floor(q.x*grid.width))),y=Math.max(0,Math.min(grid.height-1,Math.floor(q.y*grid.height))),i=y*grid.width+x;$('map-hover').textContent=fmt(grid.values[i],1)+' m · slope '+fmt(grid.slopes[i],1)+'°';}});
$('mission-region').onchange=()=>loadRegion(regions.find(r=>r.id===$('mission-region').value));
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(!grid||loadingRegion)return;mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});canvas.style.cursor=mode==='pan'?'grab':'crosshair';$('pick-help').textContent=mode==='pan'?'Drag to explore; scroll or use +/− to zoom.':mode==='zone'?'Click to add a scenario exclusion circle (radius '+fmt(Math.min(150,grid.width*grid.dx*.05),0)+' m).':`Click to move ${mode==='start'?'the start':'the target'}. Snaps to the nearest ${fmt(grid.dx,2)} m node.`;});
form.onsubmit=e=>{e.preventDefault();calculate();};form.addEventListener('input',invalidate);
for(const id of ['map-layer','show-blocked','show-direct','show-shortest','show-search'])$(id).onchange=()=>{baseImage=null;draw();};
for(const id of ['season','hour'])$(id).onchange=async()=>{invalidate();try{await loadClimate();}catch{}};
$('apply-points').onclick=()=>{if(!grid||loadingRegion)return;const points=['start','goal'].map(name=>({lat:Number($(name+'-lat').value),lon:Number($(name+'-lon').value)}));if(points.some(p=>!Number.isFinite(p.lat)||!Number.isFinite(p.lon)||Math.abs(p.lat)>90||Math.abs(p.lon)>180)){ $('status').textContent='Enter valid coordinates';return;}[start,goal]=points;pointInputs();invalidate();};
$('clear-zones').onclick=()=>{exclusions=[];pointInputs();invalidate();};
$('demo').onclick=async()=>{if(!dem||loadingRegion)return;form.reset();start={...dem.anchors.start};goal={...dem.anchors.goal};exclusions=[];pointInputs();invalidate();try{await loadClimate();await calculate();}catch{}};
$('jury-toggle').onclick=()=>{const on=document.body.classList.toggle('jury-mode');$('jury-toggle').setAttribute('aria-pressed',String(on));};
$('print').onclick=()=>window.print();
$('export').onclick=()=>{if(!report)return;const {visited,blocked,...clean}=report;const output={schema:'ares-rover-route/1',generatedAt:new Date().toISOString(),scope:'Finite 8-neighbour graph at '+grid.dx+' m; return along same path when enabled. Model optimality, not operational safety.',region,input:{start,goal,exclusions},terrain:{source:dem.provenance,bounds:dem.bounds,aggregation:grid.factor+'x'+grid.factor+' mean height; max native slope; strict no-data; edge slope check; no diagonal corner cutting'},climate,report:clean,elapsedMs,unknowns:['Wheel-scale rocks','Bearing capacity and sand','Actual crew and rover specifications','Current weather and radiation','Communications and shelters']};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ares-rover-route.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('retry').onclick=load;load();
